import java.util.LinkedHashMap;
import java.util.Map;

public class QueryStringCodecTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static int sizeOf(Map<String, String> map) {
        return map == null ? -1 : map.size();
    }

    static String valueOf(Map<String, String> map, String key) {
        return map == null ? "no map" : String.valueOf(map.get(key));
    }

    public static void main(String[] args) {
        try {
            Map<String, String> two = new LinkedHashMap<>();
            two.put("a", "1");
            two.put("b", "2");
            check("buildQuery joins two entries", "a=1&b=2", QueryStringCodec.buildQuery(two));

            Map<String, String> empty = new LinkedHashMap<>();
            check("buildQuery of an empty map", "", QueryStringCodec.buildQuery(empty));

            Map<String, String> nullValue = new LinkedHashMap<>();
            nullValue.put("flag", null);
            nullValue.put("q", "hi");
            check("a null value becomes an empty value", "flag=&q=hi",
                    QueryStringCodec.buildQuery(nullValue));

            Map<String, String> parsed = QueryStringCodec.parseQuery("a=1&b=2");
            check("parseQuery size", 2, sizeOf(parsed));
            check("parseQuery value for a", "1", valueOf(parsed, "a"));
            check("parseQuery value for b", "2", valueOf(parsed, "b"));

            Map<String, String> leading = QueryStringCodec.parseQuery("?name=ada");
            check("a leading ? is ignored", "ada", valueOf(leading, "name"));

            Map<String, String> odd = QueryStringCodec.parseQuery("flag&&a=1=2&a=9");
            check("odd query size", 2, sizeOf(odd));
            check("a bare key gets an empty value", "", valueOf(odd, "flag"));
            check("a repeated key keeps the last value", "9", valueOf(odd, "a"));

            check("null query parses to an empty map", 0, sizeOf(QueryStringCodec.parseQuery(null)));
            check("empty query parses to an empty map", 0, sizeOf(QueryStringCodec.parseQuery("")));

            Map<String, String> only = QueryStringCodec.parseQuery("x=1=2");
            check("only the first = splits the pair", "1=2", valueOf(only, "x"));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

