import java.util.LinkedHashMap;
import java.util.Map;

/**
 * TASK: Build and take apart the query-string half of a URL.
 *
 * buildQuery(params) joins the entries as key=value with '&' between them,
 * keeping the map's iteration order. A null value is written as an empty value.
 *   {a=1, b=2}      -> "a=1&b=2"
 *   {q=hello}       -> "q=hello"
 *   {}              -> ""
 *   {flag=null}     -> "flag="
 *
 * parseQuery(query) does the reverse into a LinkedHashMap (insertion order):
 *   "a=1&b=2"       -> {a=1, b=2}
 *   "?a=1"          -> {a=1}      a single leading '?' is ignored
 *   "flag"          -> {flag=}    a pair with no '=' gets an empty value
 *   "a=1&&b=2"      -> {a=1, b=2} empty pairs are skipped
 *   "a=1&a=2"       -> {a=2}      a repeated key keeps the LAST value
 *   ""  or null     -> {}
 * Only the FIRST '=' separates key from value, so "a=1=2" maps a to "1=2".
 *
 * These methods do no percent-encoding -- they only split and join.
 */
public class QueryStringCodec {

    public static String buildQuery(Map<String, String> params) {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, String> entry : params.entrySet()) {
            if (sb.length() > 0) {
                sb.append('&');
            }
            sb.append(entry.getKey()).append('=');
            if (entry.getValue() != null) {
                sb.append(entry.getValue());
            }
        }
        return sb.toString();
    }

    public static Map<String, String> parseQuery(String query) {
        Map<String, String> result = new LinkedHashMap<>();
        if (query == null || query.isEmpty()) {
            return result;
        }
        String body = query.startsWith("?") ? query.substring(1) : query;
        for (String pair : body.split("&")) {
            if (pair.isEmpty()) {
                continue;
            }
            int eq = pair.indexOf('=');
            if (eq < 0) {
                result.put(pair, "");
            } else {
                result.put(pair.substring(0, eq), pair.substring(eq + 1));
            }
        }
        return result;
    }
}
